    delete
    from PBC_REPORT_COMPANY_DAT prp
    where prp.REPORTUUID in(
         select pr.REPORTUUID from PBC_REPORT pr
          where 1=1 

          and DATE_FORMAT(pr.STARTDATE,'%Y-%m-%d')>= #{reportStartDate,jdbcType=VARCHAR}


          and DATE_FORMAT(pr.ENDDATE,'%Y-%m-%d')>= #{reportEndDate,jdbcType=VARCHAR}


            and pr.REPORTTYPE = #{reporttype,jdbcType=VARCHAR}


	         and DEPT_CODE = #{deptCode,jdbcType=VARCHAR}


            and DEPT_CODE is null

       and pr.send_status = '01'/*只删除未报送数据*/)

